import reimport zipfilefrom io import BytesIOfrom fastapi import FastAPI, Depends, HTTPException, Query, Requestfrom fastapi.responses import Responsefrom fastapi.security import OAuth2PasswordRequestFormfrom fastapi.staticfiles import StaticFilesfrom pydantic import BaseModelfrom sqlalchemy.orm import Session, load_onlyfrom .database import Base, engine, get_db, migratefrom .models import Scan, User, AuditLog, EpssScore, KevEntry, FeedMetafrom .auth import create_token, verify_user, get_current_user, require_manager, seed_adminfrom .scanner import enqueue_scan, get_live_log, queue_lengthfrom .pdf_export import build_pdffrom .csv_export import build_csvfrom .diff import collect_cve_ids, diff_scansfrom .epss import enrich_cves, startup_feedsfrom .audit import log_auditfrom .admin import router as admin_routerfrom .containers import router as containers_routerfrom .stats import router as stats_routerBase.metadata.create_all(bind=engine)migrate()seed_admin()startup_feeds()app = FastAPI(title="Trivy GUI")app.include_router(admin_router)app.include_router(containers_router)app.include_router(stats_router)IMAGE_RE = re.compile(r"^[a-zA-Z0-9][a-zA-Z0-9._\-/:@]{1,510}$")class ScanRequest(BaseModel):    image: str    registry_user: str | None = None    registry_password: str | None = None    scan_secrets: bool = Falseclass BulkIds(BaseModel):    ids: list[int]@app.get("/health")def health_probe():    return {"status": "ok"}@app.post("/api/login")def login(request: Request, form: OAuth2PasswordRequestForm = Depends(), db: Session = Depends(get_db)):    if not verify_user(db, form.username, form.password):        log_audit(form.username, "login_failed", request=request)        raise HTTPException(401, "Błędny login lub hasło")    log_audit(form.username, "login", request=request)    return {"access_token": create_token(form.username), "token_type": "bearer"}@app.post("/api/scan")def start_scan(req: ScanRequest, request: Request, db: Session = Depends(get_db),               user: User = Depends(require_manager)):    if not IMAGE_RE.match(req.image):        raise HTTPException(400, "Nieprawidłowa nazwa obrazu")    scan = Scan(image=req.image, created_by=user.username)    db.add(scan)    db.commit()    db.refresh(scan)    enqueue_scan(scan.id, req.image, req.registry_user, req.registry_password, req.scan_secrets)    log_audit(user.username, "scan_start", req.image, details=f"id={scan.id}", request=request)    return scan.summary()@app.delete("/api/scans/{scan_id}")def delete_scan(scan_id: int, request: Request, db: Session = Depends(get_db),                user: User = Depends(require_manager)):    scan = db.get(Scan, scan_id) or _404()    image = scan.image    db.delete(scan)    db.commit()    log_audit(user.username, "scan_delete", image, details=f"id={scan_id}", request=request)    return {"ok": True}@app.post("/api/scans/bulk-delete")def bulk_delete_scans(req: BulkIds, request: Request, db: Session = Depends(get_db),                      user: User = Depends(require_manager)):    if not req.ids:        raise HTTPException(400, "Brak zaznaczonych skanów")    deleted = db.query(Scan).filter(Scan.id.in_(req.ids)).delete(synchronize_session=False)    db.commit()    log_audit(user.username, "scan_bulk_delete", details=f"deleted={deleted}", request=request)    return {"ok": True, "deleted": deleted}@app.get("/api/scans")def list_scans(db: Session = Depends(get_db), user: User = Depends(get_current_user)):    scans = (        db.query(Scan)        .options(load_only(            Scan.id, Scan.image, Scan.status, Scan.error,            Scan.created_at, Scan.finished_at,            Scan.critical, Scan.high, Scan.medium, Scan.low, Scan.unknown,            Scan.secrets_enabled, Scan.secrets_found, Scan.created_by,        ))        .order_by(Scan.created_at.desc())        .limit(200)        .all()    )    return [s.summary() for s in scans]@app.get("/api/scans/diff")def scan_diff(a: int = Query(...), b: int = Query(...),              db: Session = Depends(get_db),              user: User = Depends(get_current_user)):    if a == b:        raise HTTPException(400, "Wybierz dwa różne skany")    sa = db.get(Scan, a)    sb = db.get(Scan, b)    if not sa or not sb:        raise HTTPException(404, "Nie znaleziono skanu")    if sa.image != sb.image:        raise HTTPException(400, "Porównanie możliwe tylko dla tego samego obrazu")    if sa.status != "done" or sb.status != "done":        raise HTTPException(400, "Oba skany muszą być zakończone")    if (sa.created_at or sa.id) > (sb.created_at or sb.id):        sa, sb = sb, sa    ids = list(set(collect_cve_ids(sa.result_json) + collect_cve_ids(sb.result_json)))    return diff_scans(sa, sb, enrich_cves(db, ids))@app.get("/api/scans/{scan_id}")def scan_detail(scan_id: int, db: Session = Depends(get_db),                user: User = Depends(get_current_user)):    scan = db.get(Scan, scan_id) or _404()    epss = enrich_cves(db, collect_cve_ids(scan.result_json))    return {**scan.summary(), "report": scan.result_json, "epss": epss}@app.get("/api/scans/{scan_id}/logs")def scan_logs(scan_id: int, db: Session = Depends(get_db),             user: User = Depends(get_current_user)):    scan = db.get(Scan, scan_id) or _404()    live = get_live_log(scan_id)    return {"logs": live if live is not None else (scan.log or ""), "status": scan.status}@app.get("/api/queue")def queue_status(user: User = Depends(get_current_user)):    return {"pending_jobs": queue_length()}@app.post("/api/scans/export/zip")def bulk_export_zip(req: BulkIds, request: Request, db: Session = Depends(get_db),                    user: User = Depends(get_current_user)):    if not req.ids:        raise HTTPException(400, "Brak zaznaczonych skanów")    scans = db.query(Scan).filter(Scan.id.in_(req.ids)).all()    if not scans:        raise HTTPException(404, "Nie znaleziono skanów")    buf = BytesIO()    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as zf:        for s in scans:            safe_name = s.image.replace('/', '_').replace(':', '_')            zf.writestr(f"trivy_{safe_name}_{s.id}.json", s.result_json or "{}")            ids = collect_cve_ids(s.result_json)            zf.writestr(f"trivy_{safe_name}_{s.id}.csv", build_csv(s, enrich_cves(db, ids)))    buf.seek(0)    log_audit(user.username, "export_zip", details=f"count={len(scans)}", request=request)    return Response(buf.getvalue(), media_type="application/zip",                    headers={"Content-Disposition": 'attachment; filename="trivy_scans_export.zip"'})@app.get("/api/scans/{scan_id}/export/json")def export_json(scan_id: int, request: Request, db: Session = Depends(get_db),                user: User = Depends(get_current_user)):    scan = db.get(Scan, scan_id) or _404()    fname = f"trivy_{scan.image.replace('/', '_').replace(':', '_')}.json"    log_audit(user.username, "export_json", scan.image, details=f"id={scan_id}", request=request)    return Response(scan.result_json or "{}", media_type="application/json",                    headers={"Content-Disposition": f'attachment; filename="{fname}"'})@app.get("/api/scans/{scan_id}/export/csv")def export_csv(scan_id: int, request: Request, db: Session = Depends(get_db),               user: User = Depends(get_current_user)):    scan = db.get(Scan, scan_id) or _404()    ids = collect_cve_ids(scan.result_json)    data = build_csv(scan, enrich_cves(db, ids))    fname = f"trivy_{scan.image.replace('/', '_').replace(':', '_')}.csv"    log_audit(user.username, "export_csv", scan.image, details=f"id={scan_id}", request=request)    return Response(data, media_type="text/csv; charset=utf-8",                    headers={"Content-Disposition": f'attachment; filename="{fname}"'})@app.get("/api/scans/{scan_id}/export/pdf")def export_pdf(scan_id: int, request: Request, db: Session = Depends(get_db),               user: User = Depends(get_current_user)):    scan = db.get(Scan, scan_id) or _404()    if scan.status != "done":        raise HTTPException(400, "Skan nie jest zakończony")    fname = f"trivy_{scan.image.replace('/', '_').replace(':', '_')}.pdf"    ids = collect_cve_ids(scan.result_json)    log_audit(user.username, "export_pdf", scan.image, details=f"id={scan_id}", request=request)    return Response(build_pdf(scan, enrich_cves(db, ids)), media_type="application/pdf",                    headers={"Content-Disposition": f'attachment; filename="{fname}"'})def _404():    raise HTTPException(404, "Nie znaleziono skanu")app.mount("/", StaticFiles(directory="app/static", html=True), name="static")